507	          : null,
508	        next: upcoming.slice(),
509	        score: score,
510	        level: level,
511	        lines: lines,
512	        status: status
513	      };
514	    }
515	  };
516	
517	  // ---- Player input ----
518	  var KEYS = {
519	    ArrowLeft: "left",
520	    ArrowRight: "right",
521	    ArrowDown: "softDrop",
522	    ArrowUp: "rotateCW",
523	    x: "rotateCW",
